<script lang="ts">
  import { Link2 } from "@lucide/svelte";import { locale,t,formatDateTime } from "./i18n";import { permissionLabel,statusLabel } from "./session-ui";import { providerDisplayName } from "./provider-display";export let api:(path:string,init?:RequestInit)=>Promise<any>;export let chainId:string;export let onopen:(sessionId:string)=>void=()=>{};let data:any=null,error="",expanded=false;
  api(`/api/work-chains/${chainId}`).then(value=>data=value).catch(e=>error=e instanceof Error?e.message:String(e));
  const relation=(session:any)=>{const type=data?.links?.find((link:any)=>link.targetSessionId===session.sessionId)?.relationType;return type?$t(`chain.relation.${type}`):session.sessionId===data?.chain?.rootSessionId?$t("chain.original"):$t("chain.linked");};
  const sessions=()=>{const rows=data?.sessions??[];return expanded?rows:rows.slice(0,3);};
</script>
<section class="chain"><header><Link2 size={17}/><span><strong>{data?.chain?.title??$t("chain.title")}</strong>{#if data}<small>{$t("chain.summary",{sessions:data.sessions?.length??0,hosts:[...new Set((data.sessions??[]).map((item:any)=>item.hostId))].length})}</small>{/if}</span></header>{#if error}<p>{error}</p>{:else if !data}<p>{$t("common.loading")}</p>{:else}<ol>{#each sessions() as session,index}<li><button type="button" onclick={()=>onopen(session.sessionId)}><span class="node">●</span><span><strong>{providerDisplayName(session.provider)} · {session.hostId}</strong><small>{relation(session)} · {statusLabel(session.status)} · {session.permissionProfile?permissionLabel(session.permissionProfile):$t("chain.defaultPermission")}</small><em>{session.title}</em><time>{formatDateTime(session.updatedAt,$locale)}</time></span></button>{#if index<sessions().length-1}<i></i>{/if}</li>{/each}</ol>{#if (data.sessions?.length??0)>3}<button type="button" class="branches" onclick={()=>expanded=!expanded}>{expanded?$t("chain.collapseBranches"):$t("chain.moreBranches",{count:(data.sessions?.length??0)-3})}</button>{/if}{/if}</section>
<style>.chain{border:1px solid var(--line);border-radius:14px;padding:.7rem}.chain header{display:flex;gap:.4rem;align-items:center}.chain header span{display:grid}.chain ol{list-style:none;margin:.6rem 0 0;padding:0}.chain li{position:relative}.chain button{display:grid;grid-template-columns:auto 1fr;gap:.5rem;text-align:left;width:100%;padding:.55rem;background:transparent}.chain button span:last-child{display:grid}.chain small,.chain time,.chain p{color:var(--muted);font-size:.75rem}.chain em{font-style:normal;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.node{color:var(--accent)}.chain li i{display:block;width:1px;height:16px;background:var(--line);margin-left:.72rem}.chain .branches{display:block;width:100%;min-height:40px;color:var(--muted);border-style:dashed}</style>
